const action = msg._req && msg._req.action;
if (action !== 'data-sources.list') {
    msg._result = { ok: false, errors: { action: 'data-sources: unknown action: ' + action } };
    return msg;
}

const FEED_KEYS = [
    { key: 'latest_meters',    type: 'meter',   topic: 'facis.iot.meters.v1',  protocol: 'kafka', name: 'Smart Meters' },
    { key: 'latest_pv',        type: 'pv',      topic: 'facis.iot.pv.v1',      protocol: 'kafka', name: 'PV Systems' },
    { key: 'latest_weather',   type: 'weather', topic: 'facis.iot.weather.v1', protocol: 'kafka', name: 'Weather Stations' },
    { key: 'latest_price',     type: 'price',   topic: 'facis.iot.prices.v1',  protocol: 'kafka', name: 'Energy Price Feed' },
    { key: 'latest_consumers', type: 'load',    topic: 'facis.iot.loads.v1',   protocol: 'kafka', name: 'Consumer Devices' }
];

const now = Date.now();
const sources = [];

for (const f of FEED_KEYS) {
    const arr = global.get(f.key) || [];
    // tab-feeds writes either an array or an id-keyed object — normalise.
    const list = Array.isArray(arr) ? arr : Object.values(arr);
    let lastTs = null;
    for (const item of list) {
        const ts = item && (item.timestamp || item.ts || item.observed_at || null);
        if (ts && (!lastTs || new Date(ts).getTime() > new Date(lastTs).getTime())) lastTs = ts;
    }
    // Clamp to 0: lastTs comes from sim-clock-published events which run
// ahead of wall-clock at acceleration > 1, so wall_clock - sim_time is
// negative. A negative 'age' is meaningless to a UI; show 0 (just now)
// instead of '-2,851,200 seconds ago'.
const rawMs = lastTs ? (now - new Date(lastTs).getTime()) : null;
const ageMs = rawMs == null ? null : Math.max(0, rawMs);
    let status = 'unknown';
    if (lastTs) {
        if (ageMs <= 5 * 60000)       status = 'healthy';
        else if (ageMs <= 30 * 60000) status = 'degraded';
        else                          status = 'stale';
    } else if (list.length === 0) {
        status = 'inactive';
    }
    sources.push({
        id: f.key, name: f.name, type: f.type, protocol: f.protocol, topic: f.topic,
        entity_count: list.length,
        last_event_ts: lastTs,
        last_event_age_seconds: ageMs ? Math.round(ageMs / 1000) : null,
        status
    });
}

// Static row for the SFTP DSP Drop channel — not in the simulation feeds.
const engine = global.get('engine') || {};
sources.push({
    id: 'sftp_dsp_drop', name: 'DSP SFTP Drop', type: 'transfer', protocol: 'sftp', topic: null,
    entity_count: (global.get('transfers') || []).length || 0,
    last_event_ts: engine.simulation_time || null,
    last_event_age_seconds: null,
    status: 'configured'
});

msg._result = { ok: true, data: { sources, count: sources.length, engine_state: engine.state || 'unknown' } };
return msg;
